import numpy as np

def kernel_matrix(X, kind='rbf', gamma=0.5):
    if kind == 'linear':
        return X @ X.T
    sq = np.sum((X[:, None, :] - X[None, :, :]) ** 2, -1)
    return np.exp(-gamma * sq)

def svm_predict(Xtr, ytr, alpha, b, Xte, kind='rbf', gamma=0.5):
    # 决策函数：f(x) = sum_i alpha_i y_i K(x_i, x) + b
    if kind == 'linear':
        Kte = Xte @ Xtr.T
    else:
        sq = np.sum((Xte[:, None, :] - Xtr[None, :, :]) ** 2, -1)
        Kte = np.exp(-gamma * sq)
    return np.sign(Kte @ (alpha * ytr) + b)
